import{b as o,O as r,g as n,j as s}from"./chunks/framework.DSt9LnBW.js";const q=JSON.parse('{"title":"今天讲一讲产品的生命周期","description":"记得之前有次面试的时候我问过一个候选人：你觉得我们现在这个产品，处在生命周期的哪个阶段？","frontmatter":{"date":"2026-09-25T00:00:00.000Z","tags":["互联网","产品","行业观察","职业生涯"],"sidebar":false,"pageClass":"blog-post","prev":false,"next":false,"lastUpdated":false},"headers":[],"relativePath":"blog/internet-years/product-lifecycle/index.md","filePath":"个人博客/在互联网的那些年/1.今天讲一讲产品的生命周期.md","lastUpdated":1790295671000}'),l={name:"blog/internet-years/product-lifecycle/index.md"};function g(a,t,i,p,e,d){return r(),n("div",null,[...t[0]||(t[0]=[s('<h1 id="今天讲一讲产品的生命周期" tabindex="-1">今天讲一讲产品的生命周期 <a class="header-anchor" href="#今天讲一讲产品的生命周期" aria-label="Permalink to &quot;今天讲一讲产品的生命周期&quot;">​</a></h1><p>记得之前有次面试的时候我问过一个候选人：你觉得我们现在这个产品，处在生命周期的哪个阶段？</p><p>他愣了一下，说：成长期吧。</p><p>我问为什么。他说：因为还在招人啊。</p><p>这个答案我记了很久。它不算错，但恰好说明了一件事——<strong>大部分人不是不知道有生命周期这回事，而是不知道自己在哪一段，也不知道知道这件事有什么用</strong>。</p><h2 id="一、教科书那条曲线-是不存在的" tabindex="-1">一、教科书那条曲线，是不存在的 <a class="header-anchor" href="#一、教科书那条曲线-是不存在的" aria-label="Permalink to &quot;一、教科书那条曲线，是不存在的&quot;">​</a></h2><p>所有讲产品生命周期的材料，都会给你画同一条曲线：导入、成长、成熟、衰退，四个阶段依次排开，销量和时间的关系是一条漂亮的钟形。</p><p>问题在于——<strong>这条曲线是统计出来的，不是推导出来的</strong>。</p><p>它是研究者回看一堆已经死掉或者活下来的产品，把它们的销量数据画在图上，发现大致都是这个形状，然后总结成规律。也就是说，它是<strong>后视镜里的东西</strong>。你拿着一条从后视镜里看到的曲线去判断自己现在在哪，跟闭着眼开车没区别。</p><p>真实的曲线长什么样？常见的就三种，没有一种像教科书画的那么平滑：</p><p><img src="https://op.yychuiyan.com/docs-blog/product-lifecycle-curve.png" alt="四格对比：左上教科书那条平滑的钟形曲线（灰色虚线，导入成长成熟衰退四段分明），右上锯齿型（转型一次一个锯齿，某一款突然对了才真增长），左下平台型（爬到量级就贴着天花板走），右下断崖型（外部变量半个月把上升曲线拍平）"></p><p><strong>锯齿型</strong>。转型一次，就是一个锯齿。很多公司的真实轨迹不是一款产品的曲线，而是若干个短命产品叠加起来的——真正的增长来自其中某一个突然对了，前面那些全是学费。你能记住的那些大产品，是幸存者样本。</p><p><strong>平台型</strong>。爬到某个量级就上不去了，然后长期贴着天花板走。工具类、垂类产品大多是这种。它不是死了，但也谈不上活着——用户还在，就是不再长了。</p><p><strong>断崖型</strong>。政策、竞品、资金、母公司战略，任何一个外部变量都能在半个月内把一条上升曲线拍平。这种死法跟产品做得好不好基本无关。</p><p>所以这张图真正的价值，不是让你预测自己会怎么走，而是逼你回答一个更实际的问题：</p><p><strong>如果不知道自己在哪一段，你会用错力气。</strong></p><p>这才是重点。因为——</p><h2 id="二、同一个动作-在不同阶段的含义是相反的" tabindex="-1">二、同一个动作，在不同阶段的含义是相反的 <a class="header-anchor" href="#二、同一个动作-在不同阶段的含义是相反的" aria-label="Permalink to &quot;二、同一个动作，在不同阶段的含义是相反的&quot;">​</a></h2><p>这是我这篇最想讲的一句话，我们一条条看：</p><table tabindex="0"><thead><tr><th>动作</th><th>导入期做</th><th>成熟期做</th></tr></thead><tbody><tr><td>加功能</td><td>逃避需求验证</td><td>延缓不可避免的衰退</td></tr><tr><td>招人</td><td>增加固定成本</td><td>在收缩期埋下隐患</td></tr><tr><td>建自动化/做压测</td><td>过度投资，需求可能整个被推翻</td><td>必需品，回归成本已经压不住</td></tr><tr><td>重写架构</td><td>找死</td><td>找死得慢一点</td></tr><tr><td>做增长投放</td><td>给漏水的桶加水</td><td>花钱买已经不缺的用户</td></tr></tbody></table><p>同一件事，早做三年和晚做三年，效果完全反着来。而判断&quot;早&quot;还是&quot;晚&quot;，唯一的依据就是<strong>你现在在哪个阶段</strong>。</p><p>这就是为什么值得认真对待这件事。下面逐段讲。</p><p><img src="https://op.yychuiyan.com/docs-blog/product-lifecycle.png" alt="产品生命周期流程图：导入期找 PMF → 成长期跑通规模 → 成熟期抠效率 → 衰退期收割/转型/关停，每阶段旁挂对应死法"></p><h2 id="三、导入期-0→1-找-pmf" tabindex="-1">三、导入期 0→1：找 PMF <a class="header-anchor" href="#三、导入期-0→1-找-pmf" aria-label="Permalink to &quot;三、导入期 0→1：找 PMF&quot;">​</a></h2><p>这个阶段的特征很鲜明：需求没被验证，用户少得可怜（几十到几百），团队里没有一个人说得清明天该做什么。</p><p><strong>唯一的目标是验证&quot;有人真的需要&quot;，不是增长。</strong></p><p>指标要盯的是<strong>留存</strong>。次留、周留、有没有人主动回来。一万个人来了就走，不如一百个人天天来。这里有个流传很广的判据叫 40% 法则——问用户&quot;如果不能再用这个产品，你会有多失望&quot;，回答&quot;非常失望&quot;的比例超过 40%，才算摸到 PMF 的边。数字不必迷信，它背后的思路是对的：<strong>听用户怎么说不算，看他怎么做才算</strong>。</p><p>这个阶段该做的就三件事：</p><ul><li><strong>最小可用闭环</strong>。不是功能最少，而是能跑通一次完整的价值交付。用户能从头到尾把事办成，比你多给他十个按钮重要得多。</li><li><strong>贴身观察种子用户</strong>。不是看报表，是看人。看访谈、看录屏、看他在哪一步犹豫了。报表告诉你结果，人告诉你怎么会这样。</li><li><strong>小步试错</strong>。每次改动小、成本低、可回滚。</li></ul><p><strong>典型的死法：</strong></p><ul><li><strong>伪需求</strong>。自己觉得很痛，用户不觉得。最快的识别方式是看用户愿不愿意付出成本——时间、钱、或者迁移成本。嘴上说&quot;这个好&quot;但一次都不用的，是伪需求。</li><li><strong>过早优化</strong>。需求还没确认，先上微服务、先搭架构、先把自动化框架铺好。这个阶段做这些，投入很可能随着需求推翻一起归零——<strong>这也是做测试和做质量的第一个陷阱：把建设当成绩效</strong>。</li><li><strong>功能堆砌</strong>。用户说什么就做什么，最后变成一个谁都不认识的四不像。</li><li><strong>抄竞品</strong>。抄了功能，没抄场景，也没抄人家为什么做这个功能。</li></ul><h2 id="四、成长期-1→10-跑通规模" tabindex="-1">四、成长期 1→10：跑通规模 <a class="header-anchor" href="#四、成长期-1→10-跑通规模" aria-label="Permalink to &quot;四、成长期 1→10：跑通规模&quot;">​</a></h2><p>成长期的标志不是&quot;用户涨了&quot;，而是<strong>用户自己开始涨</strong>——自然流量占比上升，获客成本下降。如果增长完全靠投放撑着，那不叫成长期，那是花钱买来的假象。</p><p>这个阶段的核心矛盾是<strong>增长和稳定的对撞</strong>。用户涌进来，代码开始扛不住，技术债开始计息。</p><p><strong>该做的：</strong></p><ul><li><strong>可观测性</strong>。日志、指标、链路追踪。出问题要能定位到具体哪个环节，而不是一群人围着屏幕猜。这是所有后续稳定工作的前提。</li><li><strong>灰度和回滚</strong>。能小范围验证，能一键退回去。没有回滚能力，就没有敢发布的速度。</li><li><strong>容量规划与压测</strong>。<strong>这才是性能测试第一次真正回本的时候</strong>——因为此时此刻流量是真实在涨的，你不知道天花板在哪，一次大促就足以让用户永久流失。</li><li><strong>核心链路固化</strong>。把最关键的那几条路用自动化测试锁住。不是全量覆盖，是核心链路。</li></ul><p><strong>典型的死法：</strong></p><ul><li><strong>撑不住量</strong>。一次大促、或者一次意外上了热门，服务崩了。这种流失是不可逆的——用户不会等你修好再回来。</li><li><strong>拉新掩盖留存</strong>。花钱买增长的时候，账是算不平的。获客成本涨、留存没跟上，等到投放一停，增长立刻归零。</li><li><strong>暴力还债</strong>。发现技术债太重，停下来重写。技术上是合理的，商业上常常是自杀——你停下来的那几个月，窗口期正在关闭。</li><li><strong>组织跟不上</strong>。人数暴涨，但组织消化不了。十个人的默契，一百个人复制不了。</li></ul><h2 id="五、成熟期-10→100-抠效率与利润" tabindex="-1">五、成熟期 10→100：抠效率与利润 <a class="header-anchor" href="#五、成熟期-10→100-抠效率与利润" aria-label="Permalink to &quot;五、成熟期 10→100：抠效率与利润&quot;">​</a></h2><p>成熟期的特征是：<strong>该有的用户都有了，不该有的也不会来了</strong>。竞争对手的产品和自己越来越像，增长曲线开始走平。</p><p>指标会发生一次根本性的迁移：从&quot;增长&quot;转向 <strong>LTV/CAC、毛利、人效</strong>。</p><p>随之而来的是矛盾转移：</p><blockquote><p>向外要不到增长，就向内挤。</p></blockquote><p>这就是很多人在这个阶段的直观体感——活越来越多，人越来越少，会议越来越长，决策越来越慢。这不是某个领导的问题，而是<strong>产品周期走到这里必然发生的事</strong>。</p><p><strong>该做的：</strong></p><ul><li><strong>精细化运营</strong>。分层、召回、提频。既然拉新变贵，就把已有的用户榨出更多价值。</li><li><strong>平台化/中台</strong>。把重复的能力收敛，降低边际成本。同样的功能不要再做第三遍。</li><li><strong>效能度量</strong>。把研发效率变成可比较的数字。出发点是好的，但要小心它异化成填表和刷指标。</li></ul><p><strong>典型的死法：</strong></p><ul><li><strong>为增长而做增长</strong>。硬做新功能、硬开新市场、硬拓新人群，资源被摊薄，一个都没做成。</li><li><strong>组织僵化</strong>。决策链路变长，创新被流程杀死。早期那种&quot;谁有想法谁上&quot;的机制没了。</li><li><strong>能人流失</strong>。成熟期必然走向规则化和流程化，而这恰好会赶走当年靠野路子把产品做起来的那批人。</li><li><strong>把稳定当成目标</strong>。稳定是结果，不是目标。为了不出错而拒绝变化的产品，最后都是被外部颠覆的，而不是被自己拖垮的。</li></ul><p>顺带说一句质量视角：成熟期最直观的变化是，<strong>稳定性从&quot;保障&quot;变成了&quot;成本项&quot;</strong>。以前是&quot;我们得扛住量&quot;，现在是&quot;这套自动化到底值不值这个人力&quot;。这个转变没有对错，是周期到了。</p><h2 id="六、衰退期-判断、决断、体面" tabindex="-1">六、衰退期：判断、决断、体面 <a class="header-anchor" href="#六、衰退期-判断、决断、体面" aria-label="Permalink to &quot;六、衰退期：判断、决断、体面&quot;">​</a></h2><p>衰退期最难的不是做事，是<strong>承认</strong>。</p><p>先要分清三种情况，很多团队在这里就把自己骗了：</p><ol><li><strong>是行业在退，还是我们在退？</strong> 看大盘和自己的份额，别把份额下滑误判成行业萎缩。</li><li><strong>是需求消失了，还是被替代了？</strong> 用户去哪了，比用户走了更重要。</li><li><strong>还有没有结构性机会？</strong> 注意，&quot;再努力一点就好了&quot;不是结构性机会。</li></ol><p>判断完之后只有三条路：</p><ul><li><strong>收割</strong>。不再投入，只做变现，接受用户体验下降。商业上这是最理性的选择，情感上最难接受。</li><li><strong>转型</strong>。用现有的用户或能力找第二曲线。成功率很低，但比坐等归零强。</li><li><strong>关停</strong>。体面地退场。</li></ul><p><strong>典型的死法：</strong></p><ul><li><strong>沉没成本</strong>。投了太多、养了太久，舍不得关，于是继续投。</li><li><strong>把&quot;维持&quot;当成&quot;恢复&quot;</strong>。用战术上的勤奋，掩盖战略上的放弃。</li><li><strong>拖到没资源才转型</strong>。转型是要花资源的，等到不得不转的时候，通常是既没有钱也没有人。</li><li><strong>关停得不干不净</strong>。数据没迁、上下游没通知、定时任务还在跑、用户连一个正式的公告都找不到。产品可以下线，责任不能。</li></ul><p>还有一个更直接的层面：<strong>这个阶段最先动的是人</strong>。leader 离职、团队被抽调、熟悉的同事一个个走。身处其中很容易觉得是自己或者身边人的问题，其实不是——这是周期走到这里的正常表现。</p><h2 id="七、贯穿全程的四条线" tabindex="-1">七、贯穿全程的四条线 <a class="header-anchor" href="#七、贯穿全程的四条线" aria-label="Permalink to &quot;七、贯穿全程的四条线&quot;">​</a></h2><p>上面是分阶段看，现在换个角度横着切一刀。任何一个产品，都有四条线在同时变化：</p><table tabindex="0"><thead><tr><th></th><th>导入期</th><th>成长期</th><th>成熟期</th></tr></thead><tbody><tr><td><strong>人</strong></td><td>全能小团队，一个人扛几摊，靠信任</td><td>分工细化，开始有流程和会议</td><td>政治、博弈、优化与流失</td></tr><tr><td><strong>数据</strong></td><td>留存：有人真的需要吗</td><td>增长与转化：能不能放大</td><td>利润与人效：值不值得继续</td></tr><tr><td><strong>钱</strong></td><td>烧钱换认知（试错成本）</td><td>烧钱换规模（获客成本）</td><td>抠成本（每笔投入都要算 ROI）</td></tr><tr><td><strong>质量</strong></td><td>快速试错：轻验证、可回滚</td><td>保障规模：压测、自动化、可观测</td><td>控制成本：回归效率、稳定性开销</td></tr></tbody></table><p>这张表最该看出来的，不是每一格写了什么，而是<strong>它们是联动的</strong>。</p><p>指标一变，组织和钱的用法一定跟着变。反过来，如果指标已经转到&quot;人效&quot;了，而团队还在按&quot;增长&quot;的逻辑烧钱招人，那就说明<strong>组织的认知滞后于产品的周期</strong>——很多公司出的问题，根子都在这里。</p><h2 id="八、怎么看自己站在哪一格" tabindex="-1">八、怎么看自己站在哪一格 <a class="header-anchor" href="#八、怎么看自己站在哪一格" aria-label="Permalink to &quot;八、怎么看自己站在哪一格&quot;">​</a></h2><p>不用打听内部消息，看四个可观察的现象就够了：</p><ol><li><strong>看招人</strong>。HC 在扩还是在收？招的是什么岗——一线执行，还是管理者？</li><li><strong>看指标</strong>。开会时反复被追问的是哪个数：留存、增长、还是人效？</li><li><strong>看争论</strong>。会上在争什么？争&quot;做什么&quot;是早期，争&quot;怎么做&quot;是中期，争&quot;要不要砍、谁负责&quot;是后期。</li><li><strong>看钱</strong>。预算往哪走：获客、研发，还是省成本。这条最灵敏，也最不容易作假。</li></ol><p>知道自己在哪一格之后，下一个问题才是真正有用的：<strong>在这个阶段，能攒下什么？</strong></p><ul><li><strong>导入期</strong>练判断力——什么是真需求。这是最稀缺、也最可迁移的能力，因为它不依赖平台和资源。</li><li><strong>成长期</strong>练工程与规模——把事做稳、做大。这也是站里那一堆性能测试教程的由来，它就是被这个阶段的需求逼出来的。</li><li><strong>成熟期</strong>练效率与协作——在约束下拿结果。</li><li><strong>衰退期</strong>练取舍——知道什么时候该走。</li></ul><p>最后说一句可能不太中听的实话：</p><p><strong>大部分人以为自己练的是通用能力，其实是被阶段塑造的。</strong></p><p>在成长期做过压测的人，跳去一家成熟期公司，会发现那套东西没人要——因为不涨了，也不需要扛量了；在成熟期做过效能治理的人，去早期团队会无从下手——因为还没到需要效率的时候。</p><p>这不是能力问题，是<strong>错配</strong>。所以选机会的第一步，不该是&quot;我想要什么&quot;，而是&quot;这个产品在哪个阶段、它现在需要什么&quot;。</p><p>周期的力量远大于个人，这点得认。但周期不可选，<strong>位置可选</strong>。</p><p>知道自己站在哪一段，很多纠结会自己消解。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><p>三个可以带走的：</p><ol><li><strong>别信那条平滑曲线。</strong> 真实轨迹是锯齿、平台、断崖。它的价值不在预测，而在提醒你别用错力气。</li><li><strong>同一个动作在不同阶段的含义是相反的。</strong> 加功能、招人、建自动化，早做三年和晚做三年，效果反着来。判断早晚的唯一依据，是你在哪一段。</li><li><strong>看位置比努力更重要。</strong> 力气使在哪个阶段，决定了它是资产还是学费。</li></ol><p>如果只能记一句：<strong>大部分人的困境不是不够努力，而是力气用错了阶段。</strong></p><p>最后划一下界，免得和另一个也叫&quot;生命周期&quot;的东西混了。</p><p>这篇讲的，是<strong>产品在市场上</strong>的那条线：以年计、单向、问的是&quot;还值不值得做&quot;。</p><p>还有一条线也叫生命周期——一个版本从需求提出到上线，需求、开发、测试、上线、维护，一轮一轮循环，以周计，问的是&quot;这个版本怎么按时保质交付&quot;。它叫<strong>软件开发生命周期（SDLC）</strong>。</p><p>两者不是并列，是嵌套：SDLC 在外层的产品周期里跑很多轮。前面那张表里&quot;质量&quot;那一行——导入期轻验证、成长期上压测、成熟期算成本——本质上就是产品周期在给开发周期定预算和标准。下一篇<a href="/blog/internet-years/sdlc/">一个版本的一生</a>，讲的就是这条线。</p>',82)])])}const h=o(l,[["render",g]]);export{q as __pageData,h as default};
